const query = $json.query || {};
const pairs = [];
function addParam(key, value) {
  if (value === undefined || value === null || value === '') return;
  pairs.push(encodeURIComponent(key) + '=' + encodeURIComponent(String(value)));
}
addParam('account_id', query.account_id || 2);
for (const key of ['from_date', 'to_date', 'all', 'inbox_id']) {
  addParam(key, query[key]);
}
return [{
  json: {
    ...$json,
    mcp_url: 'http://mcp_server_prod:8000/api/reports/sgc-dashboard?' + pairs.join('&'),
  },
}];
